// A1-4b-a -- mdadm superblock parsing + conservative RAID layout probing.
//
// Golden corpus: testdata/raid-probe-golden/ (generated by an independent
// pure-Python oracle: closed-form parity placement, bitwise GF(2^8), mdadm
// superblocks assembled from md_p.h / super1.c with checksums computed there).
//
// Key invariants under test:
//   * mdadm geometry is used instead of guessing, and is verified against
//     on-disk parity before being accepted.
//   * Corrupt / inconsistent / unsupported metadata is REJECTED explicitly.
//   * Blind probing refuses to guess when candidates tie or the budget runs
//     out; it never returns a plausible-but-unverifiable member order.
//   * Probing never mutates a member image.

#include "disk/RaidProbe.h"
#include "disk/ScanSourceChain.h"

#include <cstdint>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <memory>
#include <sstream>
#include <string>
#include <vector>

using namespace phoenix;

namespace {

int g_fail = 0;
int g_checks = 0;

#define CHECK(c)                                                             \
    do {                                                                     \
        ++g_checks;                                                          \
        if (!(c)) {                                                          \
            std::cerr << "FAIL line " << __LINE__ << ": " #c "\n";           \
            ++g_fail;                                                        \
        }                                                                    \
    } while (0)

#define CHECK_MSG(c, msg)                                                    \
    do {                                                                     \
        ++g_checks;                                                          \
        if (!(c)) {                                                          \
            std::cerr << "FAIL line " << __LINE__ << ": " << (msg) << "\n";  \
            ++g_fail;                                                        \
        }                                                                    \
    } while (0)

uint64_t Fnv1a(const uint8_t* p, size_t n)
{
    uint64_t h = 0xCBF29CE484222325ull;
    for (size_t i = 0; i < n; ++i) {
        h ^= p[i];
        h *= 0x100000001B3ull;
    }
    return h;
}

std::string Hex64(uint64_t v)
{
    std::ostringstream s;
    s << std::hex << std::nouppercase << std::setw(16) << std::setfill('0') << v;
    return s.str();
}

std::string Hex32(uint32_t v)
{
    std::ostringstream s;
    s << std::hex << std::nouppercase << std::setw(8) << std::setfill('0') << v;
    return s.str();
}

std::vector<std::string> Split(const std::string& s, char sep)
{
    std::vector<std::string> v;
    size_t a = 0;
    for (;;) {
        const size_t p = s.find(sep, a);
        v.push_back(s.substr(a, p == std::string::npos ? p : p - a));
        if (p == std::string::npos) break;
        a = p + 1;
    }
    return v;
}

std::vector<std::string> Tsv(const std::string& line)
{
    return Split(line, '\t');
}

class VecReader : public IVirtualDiskReader
{
public:
    explicit VecReader(std::vector<uint8_t> bytes) : m_bytes(std::move(bytes)) {}
    uint64_t Size() const override { return m_bytes.size(); }
    bool Read(uint64_t off, void* dst, size_t len) const override
    {
        if (off > m_bytes.size() || static_cast<uint64_t>(len) > m_bytes.size() - off)
            return false;
        if (len) std::memcpy(dst, m_bytes.data() + off, len);
        return true;
    }
    const std::vector<uint8_t>& Bytes() const { return m_bytes; }
private:
    std::vector<uint8_t> m_bytes;
};

std::vector<uint8_t> Slurp(const std::string& path)
{
    std::ifstream f(path, std::ios::binary);
    if (!f) return {};
    return std::vector<uint8_t>((std::istreambuf_iterator<char>(f)),
                                std::istreambuf_iterator<char>());
}

std::string FindDir(const std::string& leaf, const std::string& probe)
{
    std::vector<std::string> candidates;
    const std::string file = __FILE__;
    const size_t slash = file.find_last_of("/\\");
    if (slash != std::string::npos) {
        const std::string tests = file.substr(0, slash);
        const size_t up = tests.find_last_of("/\\");
        if (up != std::string::npos)
            candidates.push_back(tests.substr(0, up) + "/testdata/" + leaf);
    }
    const char* rel[] = {
        "testdata/", "../testdata/", "../../testdata/",
        "../../../testdata/", "../../../../testdata/",
        "D:/dev/PhoenixRecover/testdata/"
    };
    for (const char* r : rel) candidates.push_back(std::string(r) + leaf);
    for (const std::string& d : candidates) {
        std::ifstream f(d + "/" + probe);
        if (f.good()) return d;
    }
    return {};
}

std::string JoinU32(const std::vector<uint32_t>& v)
{
    std::string s;
    for (uint32_t x : v) {
        if (!s.empty()) s += ",";
        s += std::to_string(x);
    }
    return s;
}

RaidLevel LevelFromNumber(const std::string& n)
{
    if (n == "-1") return RaidLevel::Jbod;
    if (n == "0")  return RaidLevel::Raid0;
    if (n == "1")  return RaidLevel::Raid1;
    if (n == "4")  return RaidLevel::Raid4;
    if (n == "5")  return RaidLevel::Raid5;
    if (n == "6")  return RaidLevel::Raid6;
    if (n == "10") return RaidLevel::Raid10;
    return RaidLevel::Jbod;
}

struct CaseRow
{
    std::string name, metadata, level, layout, chunk, slotOrder;
    uint32_t members = 0, supplied = 0;
    std::string missing, expectStatus, expectOrder, expectMissing;
};

// Verify a successful probe by actually reassembling the array and reading
// the virtual boot sector (a real anchor, not a tautological assertion).
void CheckReassembly(const CaseRow& row, const RaidProbeResult& res,
                     const std::vector<const IVirtualDiskReader*>& slots)
{
    std::vector<const IVirtualDiskReader*> ordered(res.config.members, nullptr);
    for (size_t p = 0; p < res.order.size() && p < ordered.size(); ++p) {
        if (res.order[p] == kMdRoleSpare) continue;
        if (res.order[p] >= slots.size()) {
            CHECK_MSG(false, row.name + ": probe returned an invalid slot index");
            return;
        }
        ordered[p] = slots[res.order[p]];
    }
    VirtualRaid raid;
    const RaidOpenResult r = raid.Open(res.config, ordered);
    CHECK_MSG(r == RaidOpenResult::Ok,
              row.name + ": reassembly failed: " + RaidOpenDetail(r));
    if (r != RaidOpenResult::Ok) return;
    uint8_t head[512] = {};
    CHECK_MSG(raid.Read(0, head, sizeof(head)), row.name + ": virtual LBA0 unreadable");
    CHECK_MSG(head[510] == 0x55u && head[511] == 0xAAu,
              row.name + ": virtual boot sector anchor missing (wrong geometry)");
}

} // namespace

int main()
{
    const std::string dir = FindDir("raid-probe-golden", "cases.tsv");
    if (dir.empty()) {
        std::cerr << "FATAL: testdata/raid-probe-golden/cases.tsv not found\n";
        return 1;
    }
    std::cout << "golden dir: " << dir << "\n";

    // ---- primitives.tsv: independent reference values --------------------
    {
        std::ifstream f(dir + "/primitives.tsv");
        std::string line;
        int rows = 0;
        while (std::getline(f, line)) {
            if (line.empty() || line[0] == '#') continue;
            const auto c = Tsv(line);
            if (c.size() < 4) continue;
            ++rows;
            if (c[0] == "fnv1a64") {
                const std::string abc = "abc";
                CHECK_MSG(Hex64(Fnv1a(reinterpret_cast<const uint8_t*>(abc.data()),
                                      abc.size())) == c[3],
                          "FNV-1a64(abc) vs Python reference");
            } else if (c[0] == "md_magic") {
                std::ostringstream s;
                s << std::hex << std::setw(8) << std::setfill('0') << kMdMagic;
                CHECK_MSG(s.str() == c[3], "mdadm magic vs published 0xa92b4efc");
            } else if (c[0] == "v1_csum") {
                std::vector<uint8_t> sb(264, 0);
                sb[0] = 0xFC; sb[1] = 0x4E; sb[2] = 0x2B; sb[3] = 0xA9;
                sb[0xDC] = 3;
                CHECK_MSG(Hex32(raid_probe_detail::Md1Checksum(sb, 3)) == c[3],
                          "v1 superblock checksum vs independent Python oracle");
            } else if (c[0] == "gf_mul" || c[0] == "gf_pow") {
                // GF vectors belong to the Python oracle's 0x11D field; the
                // C++ GF implementation is covered by tests/test_virtual_raid.
                CHECK_MSG(c[2] == c[3], std::string("oracle primitive ") + c[0]);
            }
        }
        CHECK(rows >= 5);
    }

    // ---- cases.tsv: probe status + geometry -------------------------------
    std::ifstream cf(dir + "/cases.tsv");
    std::string line;
    int cases = 0, okCases = 0;
    while (std::getline(cf, line)) {
        if (line.empty() || line[0] == '#') continue;
        const auto c = Tsv(line);
        if (c.size() < 12) continue;
        CaseRow row;
        row.name         = c[0];
        row.metadata     = c[1];
        row.level        = c[2];
        row.layout       = c[3];
        row.chunk        = c[4];
        row.members      = static_cast<uint32_t>(std::stoul(c[5]));
        row.supplied     = static_cast<uint32_t>(std::stoul(c[6]));
        row.slotOrder    = c[7];
        row.missing      = c[8];
        row.expectStatus = c[9];
        row.expectOrder  = c[10];
        row.expectMissing= c[11];
        ++cases;

        std::vector<std::unique_ptr<VecReader>> owners;
        std::vector<const IVirtualDiskReader*> slots;
        std::vector<std::vector<uint8_t>> originals;
        for (uint32_t i = 0; i < row.supplied; ++i) {
            char path[512];
            std::snprintf(path, sizeof(path), "%s/members/%s/disk%02u.bin",
                          dir.c_str(), row.name.c_str(), i);
            std::vector<uint8_t> bytes = Slurp(path);
            CHECK_MSG(!bytes.empty(), row.name + ": missing " + path);
            originals.push_back(bytes);
            owners.emplace_back(new VecReader(bytes));
            slots.push_back(owners.back().get());
        }

        RaidProbeOptions opt;
        const std::string cfgPath = dir + "/configs/" + row.name + ".conf";
        std::ifstream cfgFile(cfgPath);
        if (cfgFile.good()) {
            std::ostringstream ss; ss << cfgFile.rdbuf();
            ChainSpec spec; std::string err;
            const ChainParseResult pr = ParseChainConfig(ss.str(), spec, err);
            CHECK_MSG(pr == ChainParseResult::Ok,
                      row.name + ": config parse: " + err);
            opt = spec.probeOptions;
        }

        RaidProbe probe;
        const RaidProbeResult res = probe.Probe(slots, opt);
        CHECK_MSG(std::string(RaidProbeStatusName(res.status)) == row.expectStatus,
                  row.name + ": status " + RaidProbeStatusName(res.status) +
                  " != " + row.expectStatus + " (" + res.detail + ")");

        if (row.expectStatus == "Ok") {
            ++okCases;
            CHECK_MSG(res.config.level == LevelFromNumber(row.level),
                      row.name + ": level mismatch");
            CHECK_MSG(std::string(RaidLayoutName(res.config.layout)) == row.layout ||
                      row.level == "1",
                      row.name + ": layout " + RaidLayoutName(res.config.layout) +
                      " != " + row.layout);
            if (row.level != "1") {
                CHECK_MSG(res.config.chunkBytes == std::stoul(row.chunk),
                          row.name + ": chunk mismatch");
            }
            CHECK_MSG(JoinU32(res.order) == row.expectOrder,
                      row.name + ": order " + JoinU32(res.order) +
                      " != " + row.expectOrder);
            CHECK_MSG(JoinU32(res.config.missing) == row.expectMissing,
                      row.name + ": missing " + JoinU32(res.config.missing) +
                      " != " + row.expectMissing);
            CHECK_MSG(res.confidence > 0u && !res.evidence.empty(),
                      row.name + ": missing evidence");
            CheckReassembly(row, res, slots);
        } else {
            CHECK_MSG(res.config.members == 0u || res.status == RaidProbeStatus::Ambiguous,
                      row.name + ": refused probe must not publish a geometry");
        }

        // Read-only invariant: probing must not touch a single byte.
        for (size_t i = 0; i < owners.size(); ++i)
            CHECK_MSG(owners[i]->Bytes() == originals[i],
                      row.name + ": member " + std::to_string(i) + " was mutated");
    }
    CHECK(cases == 16);
    CHECK(okCases >= 7);

    // ---- explicit mdadm field checks --------------------------------------
    {
        std::vector<uint8_t> b = Slurp(dir + "/members/md12_raid6_rs/disk00.bin");
        CHECK(!b.empty());
        VecReader r(b);
        MdadmSuperblock sb;
        const MdadmParseResult p = ParseMdadmSuperblock(r, sb);
        CHECK(p == MdadmParseResult::Ok);
        CHECK(sb.metadata == MdadmMetadata::V1_2);
        CHECK(sb.checksumOk);
        CHECK(sb.level == 6u);
        CHECK(sb.chunkBytes == 8192u);
        CHECK(sb.raidDisks == 4u);
        CHECK(sb.dataOffset == 8192u);
        CHECK(sb.role == 2u);       // slot 0 holds array position 2
        CHECK(sb.componentBytes > 0u);
    }
    {
        std::vector<uint8_t> b = Slurp(dir + "/members/md090_raid5_ls/disk00.bin");
        CHECK(!b.empty());
        VecReader r(b);
        MdadmSuperblock sb;
        const MdadmParseResult p = ParseMdadmSuperblock(r, sb);
        CHECK(p == MdadmParseResult::Ok);
        CHECK(sb.metadata == MdadmMetadata::V090);
        CHECK(sb.checksumOk);
        CHECK(sb.level == 5u);
        CHECK(sb.chunkBytes == 16384u);
        CHECK(sb.dataOffset == 0u);
    }

    // ---- negative: tamper a superblock magic on every member -------------
    {
        std::vector<std::unique_ptr<VecReader>> owners;
        std::vector<const IVirtualDiskReader*> slots;
        for (uint32_t i = 0; i < 3; ++i) {
            char path[512];
            std::snprintf(path, sizeof(path), "%s/members/md12_raid5_ls/disk%02u.bin",
                          dir.c_str(), i);
            auto b = Slurp(path);
            CHECK(!b.empty());
            b[4096] ^= 0xFFu;               // 1.2 superblock magic at byte 4096
            owners.emplace_back(new VecReader(std::move(b)));
            slots.push_back(owners.back().get());
        }
        RaidProbeOptions opt;
        opt.allowBlind = false;             // no known plaintext supplied
        RaidProbe probe;
        const RaidProbeResult res = probe.Probe(slots, opt);
        CHECK(res.status != RaidProbeStatus::Ok);
        CHECK(res.status == RaidProbeStatus::NoLayoutFound ||
              res.status == RaidProbeStatus::Ambiguous ||
              res.status == RaidProbeStatus::MetadataRejected);
    }

    std::cout << "RaidProbe: " << g_checks << " checks, " << g_fail
              << " failures, " << cases << " cases (" << okCases << " opened)\n";
    return g_fail != 0;
}
